INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65163899', 65163899, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN JUNIOR PENGEMBANGAN FITUR PEMROGRAMAN KEGIATAN KOORDINASI PROGRAM TIGA JUTA RUMAH', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Melaksanakan pengelolaan akun pengguna serta penanganan isu teknis (troubleshooting) sesuai kebutuhan. 2. Mengoperasikan dan mengelola dashboard kegiatan pembangunan (rolling pipeline project)/PSN perumahan serta sistem informasi terkait lainnya untuk memastikan ketersediaan data yang akurat dan terkini. 3. Melaksanakan tugas lainnya sesuai arahan Direktur Perumahan dan Infrastruktur Kawasan Permukiman, Kementerian PPN/Bappenas RI.', '1. Pendidikan minimal Sl Jurusan Komputer; 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 3. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki pengalaman kerja di bidang lT (dibuktikan dengan kontrak dan/atau surat referensi kerja sebelumnya); 7. Memiliki sertifikat Introduction wireless LAN Instalation (dibuktikan dengan sertifikat). 8. Memahami konsep dasar manajemen data dan visualisasi informasi menggunakan perangkat lunak umum (Excel, Gooogle Sheet, dsb).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1981039);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65206189', 65206189, 'analyze_legacy', 'Kab. Wonogiri', 'kabkota', 'KECAMATAN BULUKERTO', 'Belanja Penambah Daya Tahan Tubuh, Program Pemberdayaan Masyarakat Desa dan Kelurahan, Kegiatan Pemberdayaan Kelurahan, Sub Kegiatan Evaluasi Kelurahan, Kelurahan Bulukerto', 'Barang', 'E-Purchasing', 'Jawa Tengah, Wonogiri (Kab.)', 8145000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Penambah Daya Tahan Tubuh, Program Pemberdayaan Masyarakat Desa dan Kelurahan, Kegiatan Pemberdayaan Kelurahan, Sub Kegiatan Evaluasi Kelurahan, Kelurahan Bulukerto', 'Belanja Makanan Extrafoding', 8145000, 'high', 'Pengadaan penambah daya tahan tubuh/makanan ekstra untuk kegiatan evaluasi kelurahan tidak tampak memiliki keterkaitan langsung dengan output substantif pemberdayaan. Dari uraian yang tersedia, belanja ini lebih menyerupai konsumsi/suplemen penunjang kegiatan dan berindikasi tidak prioritas terhadap tujuan program, sehingga seluruh nilai patut dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 1981040);
