INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65163715', 65163715, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Dokumen Analisis Data Perumahan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 93555000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Melakukan telaah serta merumuskan rekomendasi penguatan dan pengembangan data perumahan dalam rangka mendukung program tiga juta rumah. 2. Melaksanakan pengolahan dan analisis data primer maupun sekunder terkait perumahan dan kawasan permukiman. 3. Memfasilitasi pemerintah daerah dalam pengumpulan, verifikasi, dan pengolahan data perumahan serta kawasan permukiman. 4. Mengelola proses diskusi teknis, workshop, FGD, atau kegiatan lapangan guna mendukung pendalaman data dan isu. 5. Memberikan masukan substansi berbasis analisis terhadap hasil kerja tenaga ahli terkait data perumahan dan permukiman. 6. Melaksanakan tugas lainnya sesuai arahan Direktur Perumahan dan Infrastruktur Kawasan Permukiman, Kementerian PPN/Bappenas RI.', '1. Pendidikan minimal S1 dari jurusan perencanaan wilayah dan kota, studi pembangunan, dan sejenisnya. 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak); 3. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 4. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; 5. Memiliki kemampuan dalam menyusun laporan maupun dokumen secara sistematis; 6. Mampu bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk keperluan pekerjaan; 7. Memiliki pemahaman dasar terkait isu perumahan dan permukiman, serta program penanganan permukiman kumuh di Indonesia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1982509);
