INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65164776', 65164776, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN KAJIAN PENGUATAN KELEMBAGAAN DAN REGULASI AIR MINUM KEGIATAN KOORDINASI PROGRAM SWASEMBADA AIR (AIR MINUM DAN SANITASI NASIONAL)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Mengumpulkan dan menganalisis data kinerja terkait kelembagaan penyelenggara SPAM (terutama PDAM/BUMD Air Minum atau UPTD), termasuk laporan kinerja terkait; 2. Melakukan review dan pemetaan regulasi (regulatory mapping) dalam penyelenggaraan air minum; 3. Melakukan kajian literatur dan benchmarking (studi banding) terkait kebijakan, regulasi, dan praktik terbaik yang mendukung transformasi tata kelola penyelenggaraan SPAM (Sistem Penyediaan Air Minum); 4. Mendukung penyusunan draf Peta Jalan (Roadmap) penguatan kelembagaan dan penyesuaian regulasi bidang air minum; 5. Mendukung penyusunan kerangka kelembagaan dan kerangka regulasi sektor air minum dalam dokumen perencanaan pemerintah; 6. Mendukung koordinasi dan memfasilitasi rapat koordinasi tingkat nasional (lintas kementerian/lembaga, Pemda, BUMN, mitra pembangunan/donor) terkait transformasi tata kelola air minum;', '1. Pendidikan minimal Sarjana (S1) Teknik Lingkungan; 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 3. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki pengalaman dalam penyusunan regulasi pemerintah terkait air minum (dibuktikan dengan kontrak dan/atau surat referensi kerja sebelumnya); 4 Kerangka Acuan Kerja – Jasa Konsultan Junior Penguatan Kelembagaan dan Regulasi Air Minum 7. Memiliki pengalaman dalam pengolahan data kinerja penyelenggaraan air minum (dibuktikan dengan kontrak dan/atau surat referensi kerja sebelumnya); 8. Memiliki pengalaman kerja di bidang perencanaan minimal 2 tahun (dibuktikan dengan kontrak dan/atau surat referensi kerja sebelumnya); 9. Memiliki pengalaman organisasi dan mampu bekerja sama dalam tim.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1982613);
