INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65164153', 65164153, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN JUNIOR PENYUSUNAN DOKUMEN ANALISIS KEBIJAKAN TRANSFORMATIF KEGIATAN PENYUSUNAN POLICY BRIEF STRATEGIS TRANSFORMASI TATA KELOLA LINGKUP PERUMAHAN, AIR MINUM, AIR LIMBAH DOMESTIK, DAN  PERSAMPAHAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Melakukan pengumpulan data serta identifikasi awal kondisi tata kelola dan mekanisme koordinasi antarinstansi di tingkat pusat maupun daerah, termasuk pemetaan fungsi, kewenangan, serta dinamika implementasi kebijakan; 2. Menyusun strategi dan rencana aksi penguatan kelembagaan yang selaras dengan perencanaan awal, mencakup penguatan tata kelola, penguatan koordinasi lintas sektor, integrasi perencanaan pusat daerah, serta peningkatan kapasitas dan kolaborasi para pemangku kepentingan; 3. Mempersiapkan kegiatan piloting penguatan kelembagaan dan sinergi program di beberapa kota/kabupaten terpilih sebagai percontohan penerapan kebijakan transformatif pada aspek tata kelola', '1. Pendidikan minimal S2 semua jurusan; 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 3. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki kemampuan dalam melakukan review/telaah kebijakan dan/atau dokumen yang mendukung kebijakan di tingkat nasional maupun daerah; dan 7. Memiliki kemampuan dalam menyusun laporan, kajian, maupun dokumen secara sistematis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1982803);
