INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65169988', 65169988, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Junior Analisis Kelayakan Proyek Pinjaman Luar Negeri Lingkup Multilateral', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 80400000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Melaksanakan analisis kelayakan awal (early-stage feasibility) terhadap usulan proyek yang dibiayai melalui pinjaman luar negeri multilateral, mencakup kelayakan aspek teknis, ekonomi, serta kelembagaan pada proyek kegiatan pinjaman luar negeri multilateral; hal ini didahului dengan identifikasi awal dan pengumpulan informasi terkait usulan proyek pinjaman luar negeri multilateral, termasuk pengumpulan data teknis, latar belakang proyek, kebutuhan pembiayaan, serta keselarasan dengan dokumen perencanaan yang berlaku; Mendukung penyampaian analisis risiko, serta potensi manfaat pembangunan pada proyek kegiatan pinjaman luar negeri multilateral; Melakukan analisis kebijakan, pipeline serta rekomendasi kerja sama pembiayaan lingkup multilateral; Mendukung penyiapan koordinasi penyusunan dokumen kerja sama dan penyiapan proyek, seperti identification, fact-finding, dan appraisal mission, termasuk menyiapkan bahan analisis, mencatat pembahasan teknis, serta mengidentifikasi isu yang membutuhkan tindak lanjut.', '1. Diutamakan menggunakan konsultan junior dalam negeri, dibuktikan dengan identitas kewarganegaraan Indonesia, seperti Kartu Tanda Penduduk (KTP); 2. Pendidikan minimal S1 di prodi Teknik Sipil, Perencanaan Wilayah dan Kota, Ilmu Ekonomi, atau Manajemen, dibuktikan dengan ijazah jenjang pendidikan yang telah ditempuh; 3. Memiliki keterampilan dalam analisis dan konseptual yang kuat, dibuktikan dengan hasil tulisan akademik/laporan formal/kontrak kerja sebelumnya/surat referensi kerja sebelumnya/sertifikat keahlian/sertifikat pembicara; 4. Memiliki keahlian dalam analisis kelayakan proyek/manajemen proyek, dibuktikan dengan pekerjaan sebelumnya/sertifikat keahlian kerja; 5. Memiliki kemampuan bahasa Inggris yang kuat, dibuktikan dengan IELTS/TOEFL iBT, atau contoh tulisan dalam bahasa Inggris; 6. Mahir menggunakan aplikasi Microsoft Office (Word, Power Point, Excel); dan 7. Mampu bekerja dalam tim dan tenggat waktu yang padat. 8. Tidak akan menuntut kepada PPK untuk diangkat menjadi Aparatur Sipil Negara (ASN) pada Kementerian PPN/Bappenas. 9. Tidak menuntut untuk mendapatkan fasilitas berupa : - THR dan Gaji 13 - BPJS Kesehatan - BPJS Ketenagakerjaan - Fasilitas kerja berupa perangkat komputer (Seperti Laptop dan PC) dari BMN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1986062);
