INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65169778', 65169778, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Junior Analisis Kelayakan Proyek Pinjaman Luar Negeri Lingkup Bilateral', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 97200000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 Paket', 'a. Melakukan identifikasi awal dan pengumpulan informasi terkait usulan proyek pinjaman luar negeri bilateral, termasuk pengumpulan data teknis, latar belakang proyek, kebutuhan pembiayaan, serta keselarasan dengan dokumen perencanaan yang berlaku. b. Melaksanakan analisis kelayakan awal (early-stage feasibility) terhadap usulan proyek yang dibiayai melalui pinjaman luar negeri bilateral, mencakup aspek teknis, ekonomi, kelembagaan, risiko, serta potensi manfaat pembangunan pada proyek kegiatan pinjaman luar negeri bilateral. c. Mendukung penyusunan rekomendasi teknis dan strategis berdasarkan hasil analisis kelayakan, termasuk identifikasi perbaikan ruang lingkup proyek, penyempurnaan desain, serta opsi alternatif pembiayaan atau pendekatan yang lebih sesuai. d. Menyusun dan memperbarui dokumen analisis kelayakan proyek, termasuk ringkasan proyek, catatan analisis, lembar rekomendasi, serta laporan kelayakan awal untuk mendukung proses evaluasi dan pengambilan keputusan di Direktorat Pembiayaan dan Hibah Luar Negeri. e. Melakukan pengelolaan dan pembaruan data serta informasi proyek yang dianalisis, termasuk pengarsipan dokumen dan pemeliharaan basis data sebagai bahan pendukung analisis dan pelaporan. f. Mendukung kegiatan koordinasi dan komunikasi teknis dengan unit kerja terkait, kementerian/lembaga, dan pihak lain yang relevan dalam rangka pengumpulan data, klarifikasi informasi, dan penyempurnaan hasil analisis kelayakan.', '1. Pendidikan minimum Strata Satu (S-1), di prodi ekonomi pembangunan/manajemen bisnis/teknik, dibuktikan dengan ijazah jenjang pendidikan yang telah ditempuh; 2. Memiliki pengalaman kerja 2 tahun pada bidang analisis kebijakan, pembiayaan dan hibah luar negeri, serta proyek pembangunan, atau pekerjaan terkait lainnya; 3. Memiliki keterampilan dalam analisis data/tabular, menyusun laporan analisis berbasis data yang dibuktikan dengan hasil tulisan akademik/kontrak kerja sebelumnya/surat referensi kerja sebelumnya/sertifikat keahlian/sertifikat pembicara; 4. Memiliki kemampuan bahasa Inggris baik lisan maupun tulisan; 5. Diutamakan menggunakan Tenaga Ahli dalam Negeri, dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP); 6. Mahir menggunakan aplikasi Microsoft Office (Word, PowerPoint, Excel); dan 7. Mampu bekerja dalam tim dan tenggat waktu yang padat; 8. tidak akan menuntut kepada PPK untuk diangkat menjadi Aparatur Sipil Negara (ASN) pada Kementerian PPN/Bappenas; 9. Tidak menuntut untuk mendapatkan fasilitas berupa: - Gaji 13 dan THR - BPJS Kesehatan - BPJS Ketenagakerjaan - Fasilitas kerja berupa perangkat komputer (seperti Laptop dan PC) dari BMN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1986167);
