INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65172136', 65172136, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '000001 FOLU NET SINK 2030 RBC 1', 'Paket Pekerjaan Konsultan Perorangan Tenaga Ahli Bidang Komunikasi – Implementasi FOLU Net Sink 2030 Melalui Dukungan Sumber Dana Kerjasama Indonesia dan Kerajaan Norwegia Tahap Kesatu', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 240000000, 'February 2026', 'Lainnya', 1, 1, '1', 'Proyek FOLU-NC1 akan mengimplementasikan berbagai praktik guna mencapai target net zero emission program FOLU Net Sink 2030 melalui dana kontribusi dari Kerajaan Norwegia. Proyek FOLU NC-1 ini mengompilasi berbagai bentuk kegiatan yang sesuai dengan Rencana Kerja (Renja) dan Rencana Operasional (Renops) pencapaian target FOLU Net Sink 2030 dari para pihak yang disetujui sebagai Mitra Pelaksana (Implementing Partner). Mengingat beragamnya bentuk kegiatan yang diajukan oleh Implementing Partner, persiapan proyek harus memastikan bahwa penilaian yang tepat telah tersedia untuk memahami dinamika implementasi berbagai kegiatan serta dampaknya terhadap masyarakat, termasuk pada aspek komunikasi kepada para pihak yang terlibat. Di bawah pengawasan Project Manager, Tenaga Ahli Bidang Komunikasi mendukung dengan memastikan penyampaian layanan yang berkualitas tinggi, akurat, tepat waktu dan tercatat serta terdokumentasi mencakup fungsi komunikasi dan informasi Proyek Norway – FOLU Net Sink 2030 pada Kementerian Kehutanan. Peran utama dari Tenaga Ahli Bidang Komunikasi adalah untuk mengembangkan dan mengoperasionalkan sistem media publishing terkait dengan rencana bidang I-V Folu Net Sink 2030. Sistem publishing bertujuan untuk memberikan informasi kepada khalayak umum terkait hasil-hasil kegiatan bidang I-V hasil dari proyek Folu Net Sink 2030', 'Keluaran a) Menyusun serta menjalankan Strategi monitoring, evaluasi dan pembelajaran menurut jenis, metode dan waktu pelaksanaan, termasuk membuat peraturan, pedoman dan data lain yang diperlukan dalam bidang desktop publishing. b) Menyusun dan mengintegrasikan sistem yang relevan untuk kegiatan publishing dengan aspek-aspek yang tertera dalam Investment Plan FOLU Norway, rencana operasional dan rencana bidang FOLU Net Sink 2030. c) Membuat dan mengoperasionalkan Dashboard desktop publishing untuk semua Implementing Partner. d) Mengembangkan dan atau menyempurnakan modul desktop publishing dalam penerapan sistem publishing kepada staf proyek, maupun penerima manfaat melalui kegiatan capacity building dalam keilmuaan communication. e) Membantu dalam persiapan dan pelaksanaan rangkaian kegiatan FOLU Net Sink 2030 serta memastikan hasil kegiatan sesuai dengan results framework dalam dokumen Investment Plan dan masing-masing rencana bidang FOLU Net Sink 2030. f) Membantu project leader dalam menyusun laporan regular proyek seperti laporan semester, laporan tahunan, laporan tengah proyek, dan laporan akhir proyek untuk disampaikan ke PMO FOLU COLL dan ditembuskan ke BPDLH. g) Melakukan tugas lain yang ditentukan oleh pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1989688);
