INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65171886', 65171886, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '000001 FOLU NET SINK 2030 RBC 1', 'Paket Pekerjaan Konsultan Perorangan Tenaga Ahli Bidang Safeguard Lingkungan - Implementasi FOLU Net Sink 2030 Melalui Dukungan Sumber Dana Kerjasama Indonesia dan Kerajaan Norwegia Tahap Kesatu', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 276000000, 'February 2026', 'Lainnya', 1, 1, '1', 'Proyek FOLU-NC1 akan mengimplementasikan berbagai praktik guna mencapai target net zero emission program FOLU Net Sink 2030 melalui dana kontribusi dari Kerajaan Norwegia. Proyek FOLU NC-1 ini mengompilasi berbagai bentuk kegiatan yang sesuai dengan Rencana Kerja (Renja) dan Rencana Operasional (Renops) pencapaian target FOLU Net Sink 2030 dari para pihak yang disetujui sebagai Mitra Pelaksana (Implementing Partner). Mengingat beragamnya bentuk kegiatan yang diajukan oleh Implementing Partner, persiapan proyek harus memastikan bahwa penilaian yang tepat telah tersedia untuk memahami dinamika implementasi berbagai kegiatan serta dampaknya terhadap masyarakat, termasuk pada aspek perlindungan sosial dan pengarusutamaan gender. Di bawah pengawasan Project Manager, Tenaga Ahli Bidang Safeguard Lingkungan mendukung dengan memastikan penyampaian layanan Safeguard lingkungan yang berkualitas tinggi, akurat, tepat waktu dan tercatat serta terdokumentasi mencakup fungsi pengadaan Proyek Norway – FOLU Net Sink 2030 pada Kementerian Kehutanan. Peran utama dari Tenaga Ahli Bidang Safeguard Lingkungan adalah untuk mengembangkan dan mengoperasionalkan pelaksanaan safeguard lingkungan baik lingkungan yang kuat, bersama dengan alat dan instrumen safeguard yang bertujuan untuk memastikan Implementing Partner dapat menjalankan kegiatan proyek memenuhi persyaratan safeguard sosial dan lingkungan yang telah ditetapkan oleh Kementerian Kehutanan dan BPDLH. Personel juga akan melakukan penjaminan kualitas aspek safeguard lingkungan dilaksanakan sesuai dengan POP dan kerangka pengelolaan lingkungan. Bekerja sama erat dengan tim PMU Kementerian Kehutanan, penanggung jawab pada level eselon I terkait, dan PMU BPDLH untuk menyelesaikan masalah terkait safeguard sosial, juga untuk memastikan pertukaran informasi yang memadai.', 'Keluaran a) Menyusun serta menjalankan dokumen-dokumen yang dibutuhkan dalam rangka safeguard lingkungan. b) Memantau pelaksanaan safeguard lingkungan dari kegiatan proyek termasuk peningkatan kapasitas pelaksana proyek agar dapat menjalankan Kerangka Kerja Pengelolaan Sosial dan Lingkungan dan manual pelaksanannya secara partisipatif, inklusif dan berkelanjutan. c) Membangun dan menjaga kerjasama dan koordinasi yang kuat dengan implementing partner dan semua stakeholder pada level nasional dan sub-nasional termasuk pemerintah pusat dan daerah, masyarakat adat dan masyarakat lokal, masayrakat yang terkena dampak, organisasi sosial masyarakat, dan sebagainya, d) Memberi saran dan dampingan teknis kepada Kementerian Kehutanan, PMU, dan implementing partner pada tahap persiapan dan pelaksanaan safeguard. e) Melaksanakan kolaborasi dengan tim safeguard implementing partner, Kementerian Kehutanan dan BPDLH dalam mempersiapkan guidelines, standard operating procedures, tools dan catatan-catatan penting untuk digunakan yang sejalan dengan peraturan yang berlaku di pemerintah dan BPDLH. f) Monitoring dan evaluasi serta analisis terhadap kemajuan dan realisasi secara fisik atau teknis yang dilakukan implementing partner terkait bidang I - V Instrumen dan informasi menurut kebutuhan. g) Laporan identifikasi resiko lingkungan dari kegiatan proyek, pengukuran mitigasi, dan rencana aksi. Laporan juga menyampaikan anggaran dan sumberdaya untuk pelaksanaan. h) Pedoman, SOP, dan Petunjuk Teknis safeguard lingkungan sesuai peraturan pemerintah dan BPDLH. i) Melakukan tugas lain yang ditentukan oleh pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1989730);
